<section class="panel form-panel"><div class="panel-head"><div><span class="eyebrow">TRAINING MANAGEMENT</span><h2><?= $training?'Update session':'Create training session' ?></h2></div><a class="text-link" href="index.php?route=trainings">← Back to training</a></div><form method="post" action="index.php?route=trainings/save" class="form-grid"><?= csrf_field() ?><?php if($training): ?><input type="hidden" name="id" value="<?= e($training['id']) ?>"><?php endif; ?>
